 if(typeof diagnostic.stage!=='string'||!Object.hasOwn(stages,diagnostic.stage))return '';
 const reason=typeof diagnostic.validation_reason==='string'&&Object.hasOwn(reasons,diagnostic.validation_reason)?reasons[diagnostic.validation_reason]:'';
